using UnityEngine;
namespace LWS.TruckBowling {
public sealed class BowlingAI:MonoBehaviour {
 public BowlingLane lane;public int Decisions{get;private set;}public int Reversals{get;private set;}float targetX,next,steeringError,targetSpeed,stuck,reverse;Vector3 previous;
 public void Plan(){float front=float.MaxValue,total=0;int count=0;foreach(var p in lane.pins)if(p.gameObject.activeSelf&&!p.credited)front=Mathf.Min(front,p.transform.position.z);foreach(var p in lane.pins)if(p.gameObject.activeSelf&&!p.credited&&p.transform.position.z<front+1.0f){total+=p.transform.position.x;count++;}var level=lane.Owner.difficulty;float error=level==BowlingDifficulty.Easy?.38f:level==BowlingDifficulty.Normal?.13f:.035f;targetX=(count==0?lane.center:total/count)+Random.Range(-error,error)+(lane.Owner.score.RemainingPins==10?.15f:0);steeringError=Random.Range(-error,error)*2;targetSpeed=level==BowlingDifficulty.Easy?12:level==BowlingDifficulty.Normal?14:15.5f;stuck=reverse=next=0;previous=lane.truck.body.position;}
 void FixedUpdate(){if(lane==null||!lane.Driving||!lane.match.DeliveryAllowed||lane.match.Paused||lane.Owner.source!=BowlingSource.AI)return;float dt=Time.fixedDeltaTime;var t=lane.truck;var p=t.body.position;if(!lane.Committed&&Vector3.Distance(p,previous)<.012f&&Mathf.Abs(t.throttle)>.3f)stuck+=dt;else stuck=Mathf.Max(0,stuck-dt);previous=p;
  if(stuck>2.2f&&!lane.Committed){reverse=1.0f;stuck=0;Reversals++;}if(reverse>0){reverse-=dt;t.Control(new Vector2((p.x>lane.center?-1:1)*.3f,-.6f));return;}if(Time.time<next)return;var difficulty=lane.Owner.difficulty;next=Time.time+(difficulty==BowlingDifficulty.Easy?.28f:difficulty==BowlingDifficulty.Normal?.12f:.06f);Decisions++;
  float distance=Mathf.Max(5,lane.pinLine-p.z);float desired=Mathf.Atan2(targetX-p.x,distance)*Mathf.Rad2Deg;float yaw=Mathf.DeltaAngle(0,t.transform.eulerAngles.y);float headingError=Mathf.DeltaAngle(yaw,desired)+steeringError*(lane.Committed?.4f:1);float yawRate=t.body.angularVelocity.y*Mathf.Rad2Deg;float desiredRate=headingError*1.8f-yawRate*.9f;float wheelAngle=Mathf.Atan(desiredRate*Mathf.Deg2Rad*.86f/Mathf.Max(2.5f,t.Speed))*Mathf.Rad2Deg;float slick=Mathf.Pow(Mathf.Clamp01(lane.Furthest/lane.pinLine),t.handling.oilExponent);float limit=Mathf.Lerp(t.handling.approachSteer,t.handling.laneSteer,slick);float steer=Mathf.Clamp(wheelAngle/limit,-.65f,.65f);float throttle=lane.Committed?0:t.Speed<targetSpeed?1:0;t.Control(new Vector2(steer,throttle));
 }
}
}